    destination=${1:?Destination required}
    mkdir -p -- "$(dirname -- "$destination")"
    temporary=$(mktemp "${destination}.tmp.XXXXXX")
    cat > "$temporary"
    chmod "$mode" "$temporary"
    mv -Tf -- "$temporary" "$destination"

}
file_append() {
    local destination=${1:?Destination required}
    { [[ ! -f $destination ]] || cat -- "$destination"; cat; } | file_write "$destination"
}
home_link() {
    mkdir -p -- "$(dirname -- "$2")"
    ln -sfnT -- "$1" "$2"
}

firefox_user_prefs() {
    jq -r '"'"'
        .user_prefs | to_entries | sort_by(.key)[]
        | "user_pref(\(.key | tojson), \(.value | tojson));"
    '"'"' <<<"${1:?Firefox configuration required}"
}

firefox_merge_feature_policies() {
	local directory=${FIREFOX_FEATURE_POLICIES_DIR:-/etc/system/firefox-policies.d}
	local fragments=() path
	for path in "$directory"/*.json; do
		[[ ! -f $path ]] || fragments+=("$path")
	done
	jq -s '"'"'reduce .[] as $policy ({}; . * $policy)'"'"' /dev/stdin "${fragments[@]}"
}



arkenfox_require_template() {
	local template=${ARKENFOX_TEMPLATE:-/usr/share/arkenfox-user.js/user.js}
	[[ -r $template && -s $template ]] || {
		printf '"'"'Arkenfox template missing or empty: %s. Install arkenfox-user.js before applying browsers/firefox.\n'"'"' "$template" >&2
		return 1
	}
}

firefox_policies() {
	jq '"'"'
		{policies: {
			Extensions: {Install: .extensions},
			SearchEngines: {Add: [
				.search_engines[]
				| {Name: .name, URLTemplate: .template, IconURL: .icon, Alias: .alias}
			]}
		}}
	'"'"' <<<"${1:?browser configuration required}" | firefox_merge_feature_policies
}

configure() {
	arkenfox_require_template
	BROWSERS_CONFIG=$(jq -c '"'"'.extra.browsers.firefox'"'"' /run/system-configuration.json)

	# AutoConfig applies Arkenfox to the profile Firefox actually selects.
	# pref() has the same startup-reset behavior as user.js, without locking prefs.

	local firefox_dir
	firefox_dir=/usr/lib/firefox
	[[ -x $firefox_dir/firefox ]] || {
		printf '"'"'Firefox installation missing: %s\n'"'"' "$firefox_dir" >&2
		return 1
	}
	{
		# Firefox skips the first line of an AutoConfig file.
		printf '"'"'// Arkenfox plus local preferences, generated by browsers/firefox.\n'"'"'
		printf '"'"'var user_pref = pref;\n'"'"'
		cat "${ARKENFOX_TEMPLATE:-/usr/share/arkenfox-user.js/user.js}"
		printf '"'"'\n'"'"'
		firefox_user_prefs "$BROWSERS_CONFIG"
	} | file_write "$firefox_dir/arkenfox.cfg"

	# Firefox owns extension installation/updates and its search database.
	firefox_policies "$BROWSERS_CONFIG" |
		file_write "$firefox_dir/distribution/policies.json"
}

configure
'

